-- Mandate-summary tile translations (ES/DE/FR) for all 31 countries, plus restored
-- scope_intro translations for the 6 status-banner countries.

UPDATE deep_dive_page_translations SET mandate_summary = 'España aplica dos reformas independientes y complementarias que se confunden con facilidad: VeriFactu asegura el propio software de facturación, con fechas confirmadas en enero y julio de 2027, mientras que Crea y Crece exige el intercambio estructurado de facturas B2B. La ley marco de Crea y Crece ya se ha aprobado, pero la orden ministerial de desarrollo — y por tanto las fechas exactas de inicio — sigue pendiente a mediados de 2026.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Spain');
UPDATE deep_dive_page_translations SET mandate_summary = 'Spanien betreibt zwei getrennte, sich ergänzende Reformen, die leicht verwechselt werden: VeriFactu sichert die Rechnungssoftware selbst ab, mit bestätigten Terminen im Januar und Juli 2027, während Crea y Crece den strukturierten B2B-Rechnungsaustausch vorschreibt. Das Rahmengesetz von Crea y Crece wurde verabschiedet, aber die ausführende Ministerialverordnung — und damit die genauen Starttermine — steht Mitte 2026 noch aus.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Spain');
UPDATE deep_dive_page_translations SET mandate_summary = 'L''Espagne applique deux réformes distinctes et complémentaires, faciles à confondre : VeriFactu sécurise le logiciel de facturation lui-même, avec des dates confirmées en janvier et juillet 2027, tandis que Crea y Crece impose l''échange structuré de factures B2B. La loi-cadre de Crea y Crece a été adoptée, mais l''arrêté ministériel d''application — et donc les dates de début exactes — reste en attente à la mi-2026.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Spain');
UPDATE deep_dive_page_translations SET scope_intro = 'España utiliza tres sistemas paralelos que no se comunican todos de la misma manera entre sí — saber cuál se aplica en su caso importa tanto como el detalle técnico.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Spain');
UPDATE deep_dive_page_translations SET scope_intro = 'Spanien betreibt drei parallele Systeme, die nicht alle auf dieselbe Weise miteinander kommunizieren — zu wissen, welches auf Sie zutrifft, ist ebenso wichtig wie das technische Detail.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Spain');
UPDATE deep_dive_page_translations SET scope_intro = 'L''Espagne fait fonctionner trois systèmes parallèles qui ne communiquent pas tous de la même manière entre eux — savoir lequel s''applique à vous compte autant que le détail technique.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Spain');
UPDATE deep_dive_page_translations SET mandate_summary = 'La orientación del mandato del Reino Unido está confirmada — Peppol, de 4 esquinas, sin reporte en tiempo real, con el objetivo de abril de 2029 — pero las normas técnicas detalladas, el alcance exacto y cualquier fase de implementación aún no se han publicado. HMRC se ha comprometido a presentar una hoja de ruta de implementación completa en el Presupuesto de 2026 (noviembre). Las secciones siguientes se marcan como Confirmado o Pendiente del Presupuesto 2026 según corresponda.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'United Kingdom');
UPDATE deep_dive_page_translations SET mandate_summary = 'Die Richtung des britischen Mandats ist bestätigt — Peppol, 4-Ecken-Modell, keine Echtzeit-Meldung, Zieltermin April 2029 — aber die detaillierten technischen Standards, der genaue Anwendungsbereich und eine etwaige Staffelung sind noch nicht veröffentlicht. HMRC hat sich zu einem vollständigen Umsetzungsfahrplan im Haushalt 2026 (November) verpflichtet. Die folgenden Abschnitte sind entsprechend als Bestätigt oder Ausstehend bis Haushalt 2026 gekennzeichnet.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'United Kingdom');
UPDATE deep_dive_page_translations SET mandate_summary = 'L''orientation du mandat britannique est confirmée — Peppol, 4 coins, aucune déclaration en temps réel, avec pour objectif avril 2029 — mais les normes techniques détaillées, le champ d''application exact et tout échelonnement ne sont pas encore publiés. HMRC s''est engagé à présenter une feuille de route de mise en œuvre complète lors du budget 2026 (novembre). Les sections ci-dessous sont marquées Confirmé ou En attente du budget 2026 en conséquence.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'United Kingdom');
UPDATE deep_dive_page_translations SET scope_intro = 'El Reino Unido ha elegido deliberadamente el extremo opuesto del espectro respecto a Polonia o Francia — sin autoridad de compensación, y explícitamente sin flujo de transacciones en vivo hacia HMRC en el lanzamiento.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'United Kingdom');
UPDATE deep_dive_page_translations SET scope_intro = 'Das Vereinigte Königreich hat sich bewusst für das entgegengesetzte Ende des Spektrums im Vergleich zu Polen oder Frankreich entschieden — keine Freigabebehörde und ausdrücklich kein Live-Transaktionsfeed an HMRC beim Start.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'United Kingdom');
UPDATE deep_dive_page_translations SET scope_intro = 'Le Royaume-Uni a délibérément choisi l''extrémité opposée du spectre par rapport à la Pologne ou la France — aucune autorité de contrôle, et explicitement aucun flux de transactions en direct vers HMRC au lancement.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'United Kingdom');
UPDATE deep_dive_page_translations SET mandate_summary = 'El calendario por fases y el modelo de reporte de Irlanda están firmemente confirmados por Revenue, incluyendo quién entra en la Fase 1. La especificación técnica detallada — perfil de esquema exacto, detalle de la API — aún se está finalizando junto con la Autoridad Peppol irlandesa. Las secciones siguientes se marcan como Confirmado o Pendiente de especificación técnica según corresponda.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Ireland');
UPDATE deep_dive_page_translations SET mandate_summary = 'Der gestaffelte Zeitplan und das Meldemodell Irlands sind von Revenue fest bestätigt, einschließlich der Frage, wer zu Phase 1 gehört. Die detaillierte technische Spezifikation — genaues Schemaprofil, API-Details — wird noch gemeinsam mit der irischen Peppol-Behörde finalisiert. Die folgenden Abschnitte sind entsprechend als Bestätigt oder Ausstehende technische Spezifikation gekennzeichnet.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Ireland');
UPDATE deep_dive_page_translations SET mandate_summary = 'Le calendrier échelonné et le modèle de déclaration de l''Irlande sont fermement confirmés par Revenue, y compris qui relève de la phase 1. La spécification technique détaillée — profil de schéma exact, détail de l''API — est encore en cours de finalisation avec l''autorité Peppol irlandaise. Les sections ci-dessous sont marquées Confirmé ou En attente de spécification technique en conséquence.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Ireland');
UPDATE deep_dive_page_translations SET scope_intro = 'Irlanda se sitúa entre el modelo puramente descentralizado del Reino Unido y el modelo de compensación completo de Francia o Polonia — las facturas no necesitan aprobación previa del gobierno, pero los datos de las transacciones siguen fluyendo hacia Revenue en tiempo real.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Ireland');
UPDATE deep_dive_page_translations SET scope_intro = 'Irland liegt zwischen dem rein dezentralen Modell des Vereinigten Königreichs und dem vollständigen Clearing-Modell Frankreichs oder Polens — Rechnungen benötigen keine staatliche Vorabgenehmigung, aber die Transaktionsdaten fließen weiterhin in Echtzeit an Revenue.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Ireland');
UPDATE deep_dive_page_translations SET scope_intro = 'L''Irlande se situe entre le modèle purement décentralisé du Royaume-Uni et le modèle de contrôle complet de la France ou de la Pologne — les factures n''ont pas besoin d''une approbation préalable du gouvernement, mais les données de transaction continuent d''affluer vers Revenue en temps réel.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Ireland');
UPDATE deep_dive_page_translations SET mandate_summary = 'No existe un mandato federal de facturación electrónica B2B en Estados Unidos, y actualmente no se propone ninguno con un calendario fijo. Esta página describe la red voluntaria DBNAlliance y el requisito federal B2G ya existente — ambos reales hoy, ninguno obligatorio para el comercio B2B privado.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'United States');
UPDATE deep_dive_page_translations SET mandate_summary = 'Es gibt kein bundesweites B2B-E-Invoicing-Mandat in den Vereinigten Staaten, und derzeit ist keines mit festem Zeitplan vorgeschlagen. Diese Seite beschreibt das freiwillige DBNAlliance-Netzwerk und die bereits bestehende föderale B2G-Anforderung — beide heute real, keine davon für den privaten B2B-Handel verpflichtend.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'United States');
UPDATE deep_dive_page_translations SET mandate_summary = 'Il n''existe aucun mandat fédéral de facturation électronique B2B aux États-Unis, et aucun n''est actuellement proposé selon un calendrier fixe. Cette page décrit le réseau volontaire DBNAlliance et l''exigence fédérale B2G déjà existante — tous deux réels aujourd''hui, aucun n''étant obligatoire pour le commerce B2B privé.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'United States');
UPDATE deep_dive_page_translations SET scope_intro = 'Existen dos canales genuinamente independientes — DBNAlliance para B2B voluntario, y un canal de contratación federal distinto para quienes venden al gobierno.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'United States');
UPDATE deep_dive_page_translations SET scope_intro = 'Es gibt zwei wirklich getrennte Kanäle — DBNAlliance für freiwilliges B2B und einen eigenständigen Kanal für die Bundesbeschaffung für alle, die an die Regierung verkaufen.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'United States');
UPDATE deep_dive_page_translations SET scope_intro = 'Il existe deux canaux véritablement distincts — DBNAlliance pour le B2B volontaire, et un canal fédéral d''approvisionnement distinct pour quiconque vend au gouvernement.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'United States');
UPDATE deep_dive_page_translations SET mandate_summary = 'No existe un mandato de facturación electrónica B2B en Canadá, y actualmente no se propone ninguno con un plazo fijo. La única obligación real y existente es la B2G federal — los proveedores del Gobierno de Canadá deben facturar electrónicamente a través de SAP Ariba. Esta página cubre ese requisito además del estado real de todo lo demás.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Canada');
UPDATE deep_dive_page_translations SET mandate_summary = 'Es gibt kein B2B-E-Invoicing-Mandat in Kanada, und derzeit ist keines mit festem Zeitplan vorgeschlagen. Die einzige reale, bestehende Verpflichtung ist B2G auf Bundesebene — Lieferanten der kanadischen Regierung müssen elektronisch über SAP Ariba fakturieren. Diese Seite behandelt diese Anforderung sowie den ehrlichen Stand von allem anderen.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Canada');
UPDATE deep_dive_page_translations SET mandate_summary = 'Il n''existe aucun mandat de facturation électronique B2B au Canada, et aucun n''est actuellement proposé selon un calendrier fixe. La seule obligation réelle et existante est le B2G fédéral — les fournisseurs du gouvernement du Canada doivent facturer électroniquement via SAP Ariba. Cette page couvre cette exigence ainsi que l''état honnête de tout le reste.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Canada');
UPDATE deep_dive_page_translations SET scope_intro = 'Coexisten dos mundos completamente separados: un canal federal obligatorio y todo lo demás, sin regular.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Canada');
UPDATE deep_dive_page_translations SET scope_intro = 'Zwei völlig getrennte Welten existieren nebeneinander: ein verpflichtender Bundeskanal und ein unreguliertes Alles-andere.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Canada');
UPDATE deep_dive_page_translations SET scope_intro = 'Deux mondes entièrement séparés coexistent : un canal fédéral obligatoire, et tout le reste, non réglementé.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Canada');
UPDATE deep_dive_page_translations SET mandate_summary = 'Suecia no tiene un mandato B2B doméstico establecido por ley. Lo genuinamente nuevo: una investigación nacional sobre la implementación de ViDA se puso en marcha el 5 de febrero de 2026, encargada expresamente de evaluar si se debe exigir la facturación electrónica B2B/G2B doméstica, con conclusiones previstas a más tardar el 30 de noviembre de 2027.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Sweden');
UPDATE deep_dive_page_translations SET mandate_summary = 'Schweden hat kein gesetzlich verankertes inländisches B2B-Mandat. Was wirklich neu ist: Eine nationale Untersuchung zur ViDA-Umsetzung wurde am 5. Februar 2026 gestartet, mit dem ausdrücklichen Auftrag zu prüfen, ob inländisches B2B-/G2B-E-Invoicing verpflichtend werden soll; die Ergebnisse werden spätestens zum 30. November 2027 erwartet.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Sweden');
UPDATE deep_dive_page_translations SET mandate_summary = 'La Suède n''a aucun mandat B2B domestique inscrit dans la loi. Ce qui est réellement nouveau : une enquête nationale sur la mise en œuvre de ViDA a été lancée le 5 février 2026, explicitement chargée d''évaluer s''il faut rendre obligatoire la facturation électronique B2B/G2B domestique, avec des conclusions attendues au plus tard le 30 novembre 2027.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Sweden');
UPDATE deep_dive_page_translations SET scope_intro = 'No existe realmente ninguna plataforma sueca central — este es uno de los modelos más puramente descentralizados de este tracker.' WHERE lang = 'es' AND country_id = (SELECT id FROM countries WHERE name_en = 'Sweden');
UPDATE deep_dive_page_translations SET scope_intro = 'Es gibt wirklich keine zentrale schwedische Plattform — dies ist eines der reinsten dezentralen Modelle in diesem Tracker.' WHERE lang = 'de' AND country_id = (SELECT id FROM countries WHERE name_en = 'Sweden');
UPDATE deep_dive_page_translations SET scope_intro = 'Il n''existe véritablement aucune plateforme suédoise centrale — c''est l''un des modèles les plus purement décentralisés de ce tracker.' WHERE lang = 'fr' AND country_id = (SELECT id FROM countries WHERE name_en = 'Sweden');
